# ============================================================================
# CHAOS REDUX - EVENT 019 INFANTRY SPAWN
# ============================================================================
# .1 is the preserved hidden Minor Repeatable entry point. The generation,
# accounting, management, evolution, claimant, and derivative systems live in
# scripted effects; this file owns player reports, bounded country pulses, and
# the annexer-owned exact-cleanup retry dispatcher.
# ============================================================================

country_event = {
	id = chaosx.nr19.1
	title = chaosx.nr19.1.t
	hidden = yes
	is_triggered_only = yes

	immediate = {
		infantry_spawn_fire_manifestation = yes
	}
}

# Country manifestation report. Conditional descriptions select the applicable
# baseline or pre-fire evolution direction.
country_event = {
	id = chaosx.nr19.2
	title = chaosx.nr19.2.t
	desc = {
		trigger = { has_country_flag = infantry_spawn_evolution_iv_applied }
		text = chaosx.nr19.2.evolution_iv.d
	}
	desc = {
		trigger = {
			has_country_flag = infantry_spawn_evolution_iii_applied
			NOT = { has_country_flag = infantry_spawn_evolution_iv_applied }
		}
		text = chaosx.nr19.2.evolution_iii.d
	}
	desc = {
		trigger = {
			has_country_flag = infantry_spawn_evolution_ii_applied
			NOT = { has_country_flag = infantry_spawn_evolution_iii_applied }
			NOT = { has_country_flag = infantry_spawn_evolution_iv_applied }
		}
		text = chaosx.nr19.2.evolution_ii.d
	}
	desc = {
		trigger = {
			has_country_flag = infantry_spawn_evolution_i_applied
			NOT = { has_country_flag = infantry_spawn_evolution_ii_applied }
			NOT = { has_country_flag = infantry_spawn_evolution_iii_applied }
			NOT = { has_country_flag = infantry_spawn_evolution_iv_applied }
		}
		text = chaosx.nr19.2.evolution_i.d
	}
	desc = {
		trigger = {
			NOT = { has_country_flag = infantry_spawn_evolution_i_applied }
			NOT = { has_country_flag = infantry_spawn_evolution_ii_applied }
			NOT = { has_country_flag = infantry_spawn_evolution_iii_applied }
			NOT = { has_country_flag = infantry_spawn_evolution_iv_applied }
		}
		text = chaosx.nr19.2.d
	}
	picture = GFX_report_event_infantry_spawn
	is_triggered_only = yes

	option = {
		name = chaosx.nr19.2.a
		trigger = { NOT = { has_country_flag = infantry_spawn_prefire_opening_pending } }
		ai_chance = { base = constant:infantry_spawn_event_option_weight.report_acknowledgement }
	}

	option = {
		name = chaosx.nr19.2.b
		trigger = { has_country_flag = infantry_spawn_prefire_opening_pending }
		custom_effect_tooltip = chaosx.nr19.2.b.tt
		hidden_effect = {
			set_temp_variable = { infantry_spawn_prefire_opening_choice_request = constant:infantry_spawn_deferred_prefire_choice.draw }
			infantry_spawn_defer_or_resolve_prefire_opening_choice = yes
		}
		ai_chance = {
			base = constant:infantry_spawn_prefire_opening.draw_ai_base
			modifier = {
				factor = constant:infantry_spawn_prefire_opening.draw_ai_war_factor
				has_war = yes
			}
		}
	}

	option = {
		name = chaosx.nr19.2.c
		trigger = { has_country_flag = infantry_spawn_prefire_opening_pending }
		custom_effect_tooltip = chaosx.nr19.2.c.tt
		hidden_effect = {
			set_temp_variable = { infantry_spawn_prefire_opening_choice_request = constant:infantry_spawn_deferred_prefire_choice.decline }
			infantry_spawn_defer_or_resolve_prefire_opening_choice = yes
		}
		ai_chance = {
			base = constant:infantry_spawn_prefire_opening.decline_ai_base
			modifier = {
				factor = constant:infantry_spawn_prefire_opening.decline_ai_war_factor
				has_war = yes
			}
		}
	}
}

