# Pre-fire Evolution IV first-family reception. The frozen family and incident
# nonce were selected before dispatch; every country, including AI countries,
# resolves the same three-option event exactly once.
country_event = {
	id = chaosx.nr19.105
	title = chaosx.nr19.105.t
	desc = chaosx.nr19.105.d
	picture = [GetInfantrySpawnFirstFamilyReceptionPicture]
	is_triggered_only = yes

	trigger = {
		has_country_flag = infantry_spawn_first_family_reception_pending
		has_country_flag = infantry_spawn_first_family_reception_dispatched
		NOT = { has_country_flag = infantry_spawn_first_family_reception_resolved }
		NOT = { is_infantry_spawn_derivative_country = yes }
		NOT = { has_country_flag = infantry_spawn_scenario_actor }
		NOT = { has_country_flag = infantry_spawn_scenario_dynamic_breakaway }
		NOT = { has_country_flag = infantry_spawn_scenario_takeover_actor }

infantry_spawn_initialize_command_fracture_entry = {
	infantry_spawn_initialize_country_system = yes
	set_country_flag = infantry_spawn_automatic_generation_suppressed
	set_country_flag = infantry_spawn_claimant_system_active
	set_country_flag = infantry_spawn_muster_board_available
	set_variable = { infantry_spawn_country_stage = constant:infantry_spawn_stage.command_fracture }
	if = {
		limit = { infantry_spawn_has_evolution_iv = yes }
		set_country_flag = infantry_spawn_anomalous_registry_active
		set_variable = { infantry_spawn_country_stage = constant:infantry_spawn_stage.anomalous_muster }
	}
	infantry_spawn_recalculate_country_pressure = yes
	infantry_spawn_muster_board_rebuild_view = yes
	infantry_spawn_schedule_country_pulse = yes
}

infantry_spawn_fire_manifestation = {
	infantry_spawn_initialize_global_system = yes
	infantry_spawn_initialize_evolution_telemetry = yes
	infantry_spawn_maybe_advance_global_evolution = yes
	add_to_variable = { global.infantry_spawn_generation = 1 }
	set_global_flag = infantry_spawn_system_started
	set_global_flag = infantry_spawn_event_has_fired
	if = {
		limit = {
			OR = {
				NOT = { has_global_flag = infantry_spawn_evolution_counters_ready }
				has_global_flag = infantry_spawn_evolution_counter_invariant_failure
			}
		}
		infantry_spawn_begin_evolution_counter_rebuild = yes
	}
	set_temp_variable = { infantry_spawn_countries_processed_this_generation = 0 }
	set_temp_variable = { infantry_spawn_formations_before_generation = global.infantry_spawn_total_formations }
	every_country = {
		infantry_spawn_reconcile_world_evolution_memberships = yes
		infantry_spawn_reconcile_participant_evolution_memberships = yes
		if = {
			limit = { infantry_spawn_country_can_receive_generation = yes }
			if = {
				limit = { infantry_spawn_derivative_package_is_active = yes }
				infantry_spawn_derivative_process_global_manifestation = yes
			}
			else = {
				infantry_spawn_initialize_country_system = yes
				infantry_spawn_apply_prefire_evolution_entry = yes
				if = {
					limit = { infantry_spawn_has_evolution_iii = yes }
					infantry_spawn_initialize_command_fracture_entry = yes
					# Repeatable manifestations at Evolution III/IV reopen the
					# request surface with a fresh, empty generation. The request
					# context does not draw or pay for a lot; it only gives the
					# player and AI a bounded window to make an ordinary request.
					# Terminal revolt/takeover outcomes retain their historical
					# ledgers but must never reopen the ordinary category.
					if = {
						limit = {
							NOT = { has_country_flag = infantry_spawn_claimant_takeover_complete }
							NOT = { has_country_flag = infantry_spawn_achievement_revolt_history }
						}
						infantry_spawn_prepare_request_generation_context = yes
					}
				}
				else = { infantry_spawn_begin_country_generation = yes }
			}
			if = {
				limit = { is_ai = no }
				country_event = { id = chaosx.nr19.2 days = 1 }
			}
			if = {
				limit = { infantry_spawn_contributes_to_ordinary_evolution_history = yes }
				add_to_temp_variable = { infantry_spawn_countries_processed_this_generation = 1 }
			}
		}
	}
	infantry_spawn_validate_evolution_counter_state = yes
	if = {
		limit = { has_global_flag = infantry_spawn_evolution_counters_ready }
		infantry_spawn_ensure_evolution_check_is_scheduled = yes
	}
	set_variable = { global.infantry_spawn_last_generation_country_count = infantry_spawn_countries_processed_this_generation }
	set_variable = { global.infantry_spawn_last_generation_formation_count = global.infantry_spawn_total_formations }
	subtract_from_variable = { global.infantry_spawn_last_generation_formation_count = infantry_spawn_formations_before_generation }
}

# ---------------------------------------------------------------------------
# Event Log country follow-ups
# ---------------------------------------------------------------------------

# COUNTRY scope. Input: infantry_spawn_history_payload_value and optional
# Event Log secondary-actor override temporaries. The normal Event 19 firing
# count and last-fired display are restored after appending the history row.
infantry_spawn_record_country_followup_history = {
	set_temp_variable = { infantry_spawn_history_previous_last_event_id = global.last_fired_event_id }
	set_temp_variable = { events_log_history_payload_override = infantry_spawn_history_payload_value }
	set_temp_variable = { events_log_history_payload_override_active = 1 }
	set_temp_variable = { events_log_history_actor_override = THIS }
	set_temp_variable = { events_log_history_actor_override_active = 1 }
	set_variable = { global.last_fired_event_id = constant:infantry_spawn_event.id }
	record_events_log_history_entry = yes
	set_variable = { global.last_fired_event_id = infantry_spawn_history_previous_last_event_id }
}

infantry_spawn_record_claimant_appearance_history = {
	set_temp_variable = { events_log_history_secondary_actor_override_active = 0 }
	set_temp_variable = { infantry_spawn_history_payload_value = constant:infantry_spawn_history_payload.claimant_appearance }
	infantry_spawn_record_country_followup_history = yes
}

infantry_spawn_record_claimant_takeover_history = {
	set_temp_variable = { events_log_history_secondary_actor_override_active = 0 }
	set_temp_variable = { infantry_spawn_history_payload_value = constant:infantry_spawn_history_payload.claimant_takeover }
	infantry_spawn_record_country_followup_history = yes
}

